'use strict';

function meankbn(N, x, stride, offset) {
    if (N <= 0) {
        return NaN;
    }
    var sum = 0.0;
    var c = 0.0;
    var ix = offset;
    for (var i = 0; i < N; i++) {
        var y = x[ix] - c;
        var t = sum + y;
        c = (t - sum) - y;
        sum = t;
        ix += stride;
    }
    return sum / N;
}

module.exports = meankbn;
